select * from club_payable
where topic_id = #{topicId} and club_id = #{clubId} and component = #{component}
order by id

select * from club_payable
where topic_id = #{topicId} and club_id = #{clubId} and component = #{component}
order by id for update

mapper.update:
update club_payable_batch
set batch_status = 'CONFIRMED', confirmed_by = #{confirmedBy}, confirmed_at = #{confirmedAt}
where id = #{id} and batch_status = 'PENDING'

update club_payable_batch
set invoice_status = 'ISSUED', invoice_no = #{invoiceNo}
where id = #{id} and invoice_status = 'NONE'

update club_payable_batch
set invoice_status = 'RED', red_invoice_no = #{redInvoiceNo}
where id = #{id} and invoice_status = 'ISSUED'

update club_payable_batch
set batch_status = 'PAID', paid_by = #{paidBy}, paid_at = #{paidAt},
    payment_reference = #{paymentReference}
where id = #{id} and batch_status = 'CONFIRMED'
  and confirmed_by is not null and confirmed_by <> #{paidBy}
